        for event in events:
            if event[0] == "deposit":
                acct, amt = event[1], event[2]
                if amt < 0:
                    continue
                if acct not in balances:
                    balances[acct] = 0
                balances[acct] += amt
            elif event[0] == "withdraw":
                from_acct, amt = event[1], event[2]
                if amt < 0:
                    continue
                if from_acct not in balances:
                    balances[from_acct] = 0
                if balances[from_acct] >= amt:
                    balances[from_acct] -= amt
            elif event[0] == "transfer":
                from_acct, to_acct, amt = event[1], event[2], event[3]
                if amt < 0:
                    continue
                if from_acct not in balances:
                    balances[from_acct] = 0
                if to_acct not in balances:
